def make_work_words():
    words = []
    subs = ["work_office", "work_business", "work_trades", "work_career", "work_tools"]
    for i, w in enumerate(work_data):
        sub = subs[i // 50]
        words.append((w[0], w[1], w[2], f"[{w[0].lower()}]", w[3], w[4], w[5], w[6], "work", sub, w[7]))
    return words

